#include <cstdint>
#include <map>
#include <string>

bool ntSuccess(std::uint32_t status) { return static_cast<std::int32_t>(status) >= 0; }

std::string severity(std::uint32_t status)
{
    static const char* const names[]{ "success", "informational", "warning", "error" };
    return names[status >> 30];
}

std::string name(std::uint32_t status)
{
    static const std::map<std::uint32_t, std::string> known{
        { 0x00000000u, "STATUS_SUCCESS" }, { 0x00000103u, "STATUS_PENDING" }, { 0x80000005u, "STATUS_BUFFER_OVERFLOW" },
        { 0xC0000001u, "STATUS_UNSUCCESSFUL" }, { 0xC000000Du, "STATUS_INVALID_PARAMETER" }, { 0xC0000010u, "STATUS_INVALID_DEVICE_REQUEST" },
        { 0xC0000022u, "STATUS_ACCESS_DENIED" }, { 0xC0000023u, "STATUS_BUFFER_TOO_SMALL" }, { 0xC000009Au, "STATUS_INSUFFICIENT_RESOURCES" },
    };
    const auto it{ known.find(status) };
    return it == known.end() ? "" : it->second;
}

unitTests:
TEST("success codes") { CHECK(ntSuccess(0)); CHECK(ntSuccess(0x103)); CHECK_EQ(severity(0x103), std::string("success")); }
TEST("informational counts as success") { CHECK(ntSuccess(0x40000000u)); CHECK_EQ(severity(0x40000000u), std::string("informational")); }
TEST("warnings are not success") { CHECK(!ntSuccess(0x80000005u)); CHECK_EQ(severity(0x80000005u), std::string("warning")); }
TEST("errors") { CHECK(!ntSuccess(0xC0000022u)); CHECK_EQ(severity(0xC0000022u), std::string("error")); }
TEST("names") { CHECK_EQ(name(0xC000009Au), std::string("STATUS_INSUFFICIENT_RESOURCES")); CHECK_EQ(name(0x103), std::string("STATUS_PENDING")); CHECK_EQ(name(0xC0001234u), std::string("")); }

